#!/usr/bin/env node
import { join } from "node:path";
import { homedir } from "node:os";
import { existsSync, mkdirSync, readFileSync, writeFileSync, readdirSync, statSync } from "node:fs";
import { getTags, getProjectName } from "./services/tags.js";
import { CONFIG } from "./config.js";
const CONFIG_DIR = join(homedir(), ".config", "opencode");
const OPENCODE_CONFIG = join(CONFIG_DIR, "opencode.jsonc");
const OPENCODE_CONFIG_JSON = join(CONFIG_DIR, "opencode.json");
const DATA_DIR = join(homedir(), ".local", "share", "opencode-memory");
const PLUGIN_NAME = "@ninkch/opencode-mem";
function stripJsoncComments(content) {
    let result = "";
    let inString = false;
    let escape = false;
    for (let i = 0; i < content.length; i++) {
        const char = content[i];
        const nextChar = content[i + 1];
        if (escape) {
            result += char;
            escape = false;
            continue;
        }
        if (char === "\\") {
            result += char;
            escape = true;
            continue;
        }
        if (char === '"') {
            inString = !inString;
            result += char;
            continue;
        }
        if (!inString) {
            if (char === "/" && nextChar === "/") {
                while (i < content.length && content[i] !== "\n")
                    i++;
                continue;
            }
            if (char === "/" && nextChar === "*") {
                i += 2;
                while (i < content.length && !(content[i] === "*" && content[i + 1] === "/"))
                    i++;
                i++;
                continue;
            }
        }
        result += char;
    }
    return result.trim();
}
function readJsonc(path) {
    const content = readFileSync(path, "utf-8");
    return JSON.parse(stripJsoncComments(content));
}
function writeJson(path, data) {
    writeFileSync(path, JSON.stringify(data, null, 2), "utf-8");
}
function getOpenCodeConfigPath() {
    if (existsSync(OPENCODE_CONFIG))
        return OPENCODE_CONFIG;
    if (existsSync(OPENCODE_CONFIG_JSON))
        return OPENCODE_CONFIG_JSON;
    return null;
}
function formatBytes(bytes) {
    if (bytes === 0)
        return "0 B";
    const k = 1024;
    const sizes = ["B", "KB", "MB", "GB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return `${parseFloat((bytes / Math.pow(k, i)).toFixed(1))} ${sizes[i]}`;
}
function getDirSize(dir) {
    let size = 0;
    const files = readdirSync(dir);
    for (const file of files) {
        const filePath = join(dir, file);
        const stats = statSync(filePath);
        if (stats.isDirectory()) {
            size += getDirSize(filePath);
        }
        else {
            size += stats.size;
        }
    }
    return size;
}
function formatDate(ts) {
    const d = new Date(ts);
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, "0");
    const day = String(d.getDate()).padStart(2, "0");
    const hour = String(d.getHours()).padStart(2, "0");
    const min = String(d.getMinutes()).padStart(2, "0");
    const sec = String(d.getSeconds()).padStart(2, "0");
    return `${year}-${month}-${day} ${hour}:${min}:${sec}`;
}
const commands = {
    install: async () => {
        console.log(`\n  Installing ${PLUGIN_NAME}...\n`);
        if (!existsSync(CONFIG_DIR)) {
            mkdirSync(CONFIG_DIR, { recursive: true });
        }
        const configPath = getOpenCodeConfigPath();
        if (configPath && existsSync(configPath)) {
            let config;
            try {
                config = readJsonc(configPath);
            }
            catch (e) {
                console.log(`  ✗ Failed to parse config: ${configPath}`);
                console.log(`  Error: ${e instanceof Error ? e.message : String(e)}`);
                console.log(`\n  Please add manually to your config:`);
                console.log(`    "plugin": ["${PLUGIN_NAME}"]\n`);
                return;
            }
            if (config.plugin?.includes(PLUGIN_NAME)) {
                console.log(`  ✓ ${PLUGIN_NAME} is already installed\n`);
                return;
            }
            if (!config.plugin) {
                config.plugin = [];
            }
            if (!Array.isArray(config.plugin)) {
                config.plugin = [config.plugin];
            }
            config.plugin.push(PLUGIN_NAME);
            try {
                writeJson(configPath, config);
                console.log(`  ✓ Plugin registered in ${configPath}`);
            }
            catch (e) {
                console.log(`  ✗ Failed to write config`);
                console.log(`\n  Please add manually to ${configPath}:`);
                console.log(`    "plugin": ["${PLUGIN_NAME}"]\n`);
                return;
            }
        }
        else {
            const config = { plugin: [PLUGIN_NAME] };
            try {
                writeJson(OPENCODE_CONFIG_JSON, config);
                console.log(`  ✓ Created config at ${OPENCODE_CONFIG_JSON}`);
            }
            catch (e) {
                console.log(`  ✗ Failed to create config`);
                console.log(`\n  Please create ${OPENCODE_CONFIG_JSON} with:`);
                console.log(`    { "plugin": ["${PLUGIN_NAME}"] }\n`);
                return;
            }
        }
        if (!existsSync(DATA_DIR)) {
            mkdirSync(DATA_DIR, { recursive: true });
        }
        console.log(`  ✓ Created data directory: ${DATA_DIR}`);
        console.log(`\n  Next steps:`);
        console.log(`  1. Run '${PLUGIN_NAME} init' to initialize storage`);
        console.log(`  2. Restart OpenCode with: opencode -c\n`);
    },
    init: async () => {
        console.log(`\n  Initializing ${PLUGIN_NAME}...\n`);
        if (!existsSync(DATA_DIR)) {
            mkdirSync(DATA_DIR, { recursive: true });
        }
        console.log(`  ✓ Data directory created: ${DATA_DIR}`);
        // 显示模型下载提示
        console.log(`\n  Embedding model: Xenova/paraphrase-multilingual-MiniLM-L12-v2`);
        console.log(`  Size: ~420MB (downloaded automatically on first use)`);
        console.log(`\n  ✓ Initialization complete!\n`);
        console.log(`  Restart OpenCode to use local memory:`);
        console.log(`    opencode -c\n`);
    },
    status: async () => {
        console.log(`\n  ${PLUGIN_NAME} Status\n`);
        const configPath = getOpenCodeConfigPath();
        let installed = false;
        if (configPath && existsSync(configPath)) {
            try {
                const config = readJsonc(configPath);
                installed = config.plugin?.includes?.(PLUGIN_NAME) || false;
            }
            catch { }
        }
        console.log(`  Plugin: ${installed ? "✓ Installed" : "✗ Not installed"}`);
        console.log(`  Data Directory: ${DATA_DIR}`);
        console.log(`  Exists: ${existsSync(DATA_DIR) ? "✓" : "✗"}`);
        const dbPath = join(DATA_DIR, "data.db");
        if (existsSync(dbPath)) {
            const dbStats = statSync(dbPath);
            console.log(`  Database: ${formatBytes(dbStats.size)}`);
        }
        const modelsDir = join(DATA_DIR, "models");
        if (existsSync(modelsDir)) {
            const modelSize = getDirSize(modelsDir);
            console.log(`  Model Cache: ${formatBytes(modelSize)}`);
        }
        console.log();
    },
    config: async (args) => {
        const subCommand = args[0];
        if (subCommand === "show" || !subCommand) {
            const configPath = join(CONFIG_DIR, "memory.json");
            console.log(`\n  Config file: ${configPath}\n`);
            if (existsSync(configPath)) {
                console.log(readFileSync(configPath, "utf-8"));
            }
            else {
                console.log("  No config file found. Using defaults.\n");
            }
        }
        else if (subCommand === "set") {
            const key = args[1];
            const value = args[2];
            if (!key || !value) {
                console.log("  Usage: config set <key> <value>\n");
                return;
            }
            const configPath = join(CONFIG_DIR, "memory.json");
            let config = {};
            if (existsSync(configPath)) {
                config = JSON.parse(readFileSync(configPath, "utf-8"));
            }
            if (value === "true")
                config[key] = true;
            else if (value === "false")
                config[key] = false;
            else if (!isNaN(Number(value)))
                config[key] = Number(value);
            else
                config[key] = value;
            if (!existsSync(CONFIG_DIR)) {
                mkdirSync(CONFIG_DIR, { recursive: true });
            }
            writeJson(configPath, config);
            console.log(`\n  ✓ Set ${key} = ${value}\n`);
        }
        else if (subCommand === "edit") {
            const configPath = join(CONFIG_DIR, "memory.json");
            const editor = process.env.EDITOR || process.env.VISUAL || "nano";
            const { execSync } = require("node:child_process");
            execSync(`${editor} ${configPath}`, { stdio: "inherit" });
        }
    },
    memories: async (args) => {
        const subCommand = args[0];
        const { getStore } = await import("./services/store.js");
        const store = getStore();
        if (subCommand === "list") {
            const showAll = args.includes("--all");
            const projectName = args.includes("--project") ? args[args.indexOf("--project") + 1] : undefined;
            const scope = args.includes("--scope") ? args[args.indexOf("--scope") + 1] : undefined;
            const limit = args.includes("--limit") ? parseInt(args[args.indexOf("--limit") + 1]) : 100;
            let memories;
            if (showAll) {
                memories = await store.listAllMemories(limit);
            }
            else if (projectName) {
                memories = await store.listMemoriesByProject(projectName, limit);
            }
            else {
                const tags = getTags(process.cwd());
                const tag = scope === "user" ? tags.user : tags.project;
                const oldTags = scope === "user"
                    ? ["opencode-mem_user_default", "mem_user_default"]
                    : ["opencode-mem_project_default", "mem_project_default"];
                memories = await store.listMemories(tag, limit, oldTags);
            }
            console.log(`\n  Memories: ${memories.length}\n`);
            if (memories.length === 0) {
                console.log("  No memories found.\n");
                return;
            }
            memories.forEach((m) => {
                const content = m.content.length > 20 ? m.content.slice(0, 20) + "..." : m.content;
                const project = m.projectName || "跨项目";
                const created = formatDate(m.createdAt);
                console.log(`  ${m.id} | ${project} | ${content} | ${m.type} | ${created}`);
            });
            console.log();
        }
        else if (subCommand === "show") {
            const id = args[1];
            if (!id) {
                console.log("  Usage: memories show <id>\n");
                return;
            }
            const memory = await store.getMemory(id);
            if (!memory) {
                console.log(`\n  ✗ Memory not found: ${id}\n`);
                return;
            }
            console.log(`
  Memory Details:

    ID: ${memory.id}
    Project: ${memory.projectName || "跨项目"}
    Path: ${memory.projectPath || "-"}
    Type: ${memory.type}
    Scope: ${memory.scope}
    Created: ${formatDate(memory.createdAt)}
    Updated: ${formatDate(memory.updatedAt)}

  Content:
    ${memory.content}
`);
        }
        else if (subCommand === "search") {
            const query = args[1];
            if (!query) {
                console.log("  Usage: memories search <query> [--scope <user|project>] [--threshold <0-1>]\n");
                return;
            }
            const scope = args.includes("--scope") ? args[args.indexOf("--scope") + 1] : undefined;
            const thresholdArg = args.includes("--threshold") ? Number(args[args.indexOf("--threshold") + 1]) : undefined;
            const threshold = Number.isFinite(thresholdArg) ? thresholdArg : CONFIG.similarityThreshold;
            const searchOptions = { threshold, limit: 10 };
            const tags = getTags(process.cwd());
            let results;
            if (scope === "user" || scope === "project") {
                results = await store.searchMemories(query, scope === "user" ? tags.user : tags.project, searchOptions);
            }
            else {
                const [userHits, projectHits] = await Promise.all([
                    store.searchMemories(query, tags.user, searchOptions),
                    store.searchMemories(query, tags.project, searchOptions),
                ]);
                results = [...projectHits.map((r) => ({ ...r, scope: "project" })), ...userHits.map((r) => ({ ...r, scope: "user" }))]
                    .sort((a, b) => b.similarity - a.similarity)
                    .slice(0, 10);
            }
            console.log(`\n  Search results for "${query}": ${results.length}\n`);
            results.forEach((r, i) => {
                const similarity = Math.round(r.similarity * 100);
                console.log(`  ${i + 1}. [${similarity}%] [${r.scope}] ${r.content.slice(0, 60)}${r.content.length > 60 ? "..." : ""}`);
                console.log(`     ID: ${r.id}\n`);
            });
        }
        else if (subCommand === "add") {
            const contentArgs = args.slice(1).filter(a => !a.startsWith("--"));
            const scope = args.includes("--scope") ? args[args.indexOf("--scope") + 1] : "project";
            const content = contentArgs.join(" ");
            if (!content) {
                console.log("  Usage: memories add <content> [--scope <user|project>]\n");
                return;
            }
            const tags = getTags(process.cwd());
            const memory = await store.addMemory({
                content,
                scope: scope,
                type: "learned-pattern",
                containerTag: scope === "user" ? tags.user : tags.project,
                projectName: scope === "project" ? getProjectName(process.cwd()) : undefined,
                projectPath: scope === "project" ? process.cwd() : undefined,
            });
            console.log(`\n  ✓ Memory added with ID: ${memory.id}\n`);
        }
        else if (subCommand === "forget") {
        }
        else if (subCommand === "forget") {
            const id = args[1];
            if (!id) {
                console.log("  Usage: memories forget <id>\n");
                return;
            }
            const deleted = await store.deleteMemory(id);
            if (deleted) {
                console.log(`\n  ✓ Memory ${id} deleted\n`);
            }
            else {
                console.log(`\n  ✗ Memory not found\n`);
            }
        }
        else if (subCommand === "clear") {
            const confirmed = args.includes("--force");
            if (!confirmed) {
                console.log("  This will delete ALL memories. Use --force to confirm.\n");
                return;
            }
            const count = await store.clearMemories();
            console.log(`\n  ✓ Cleared ${count} memories\n`);
        }
        else {
            console.log(`
  Memory Commands:

    list [--scope <user|project>] [--all] [--project <name>] [--limit <n>]   List memories
    show <id>                                                              Show memory details
    search <query>                                                         Search memories
    add <content> [--scope <user|project>]                                 Add a memory
    forget <id>                                                            Delete a memory
    clear --force                                                          Delete all memories
`);
        }
    },
    export: async (args) => {
        const outputPath = args[0] || "memories-export.json";
        const { getStore } = await import("./services/store.js");
        const store = getStore();
        const stats = await store.getStats();
        const memories = {
            exportedAt: new Date().toISOString(),
            version: "1.0.0",
            stats,
            memories: [],
        };
        const tags = getTags(process.cwd());
        const oldProjectTags = ["opencode-mem_project_default", "mem_project_default"];
        const allMemories = await store.listMemories(tags.project, 1000, oldProjectTags);
        memories.memories = allMemories;
        writeFileSync(outputPath, JSON.stringify(memories, null, 2), "utf-8");
        console.log(`\n  ✓ Exported ${allMemories.length} memories to ${outputPath}\n`);
    },
    import: async (args) => {
        const inputPath = args[0];
        if (!inputPath || !existsSync(inputPath)) {
            console.log("  Usage: import <file>\n");
            return;
        }
        const data = JSON.parse(readFileSync(inputPath, "utf-8"));
        const { getStore } = await import("./services/store.js");
        const store = getStore();
        let imported = 0;
        const tags = getTags(process.cwd());
        for (const mem of data.memories || []) {
            const scope = mem.scope || "project";
            await store.addMemory({
                content: mem.content,
                scope,
                type: mem.type || "learned-pattern",
                containerTag: scope === "user" ? tags.user : tags.project,
                projectName: scope === "project" ? getProjectName(process.cwd()) : undefined,
                projectPath: scope === "project" ? process.cwd() : undefined,
            });
            imported++;
        }
        console.log(`\n  ✓ Imported ${imported} memories\n`);
    },
    model: async (args) => {
        const subCommand = args[0];
        if (subCommand === "clear-cache") {
            const modelsDir = join(DATA_DIR, "models");
            if (existsSync(modelsDir)) {
                const { rmSync } = require("node:fs");
                rmSync(modelsDir, { recursive: true });
                console.log(`\n  ✓ Model cache cleared\n`);
            }
            else {
                console.log(`\n  No model cache found\n`);
            }
        }
        else {
            console.log(`
  Model Commands:

    clear-cache    Clear the embedding model cache
`);
        }
    },
    logs: async () => {
        const logFile = join(DATA_DIR, "opencode-mem.log");
        if (existsSync(logFile)) {
            const content = readFileSync(logFile, "utf-8");
            const lines = content.split("\n").slice(-50);
            console.log(`\n  Last 50 log lines:\n`);
            lines.forEach((line) => console.log(`  ${line}`));
        }
        else {
            console.log("\n  No logs found\n");
        }
    },
    help: async () => {
        console.log(`
  ${PLUGIN_NAME} - Local persistent memory for OpenCode

  Usage: ${PLUGIN_NAME} <command> [options]

  Commands:

    install                Install plugin to OpenCode
    init                   Initialize storage and download model
    status                 Show plugin status
    config [show|set|edit] Manage configuration
    memories <cmd>         Manage memories (list, search, add, forget, clear)
    export [file]          Export memories to JSON
    import <file>          Import memories from JSON
    model <cmd>            Model management (clear-cache)
    logs                   View recent logs
    help                   Show this help

  Examples:

    ${PLUGIN_NAME} install
    ${PLUGIN_NAME} init
    ${PLUGIN_NAME} memories list --scope project
    ${PLUGIN_NAME} memories search "build error"
    ${PLUGIN_NAME} export my-memories.json

  More info: https://github.com/opencode-mem/opencode-mem
`);
    },
};
async function main() {
    const args = process.argv.slice(2);
    const command = args[0] || "help";
    if (commands[command]) {
        await commands[command](args.slice(1));
    }
    else {
        console.log(`\n  Unknown command: ${command}`);
        console.log(`  Run '${PLUGIN_NAME} help' for usage.\n`);
        process.exit(1);
    }
}
main().catch((e) => {
    console.error(`\n  Error: ${e.message}\n`);
    process.exit(1);
});

import { tool } from "@opencode-ai/plugin/tool";
import { getStore } from "./services/store.js";
import { formatContextForPrompt, generateUserProfile } from "./services/context.js";
import { getTags, getProjectName } from "./services/tags.js";
import { stripPrivateContent, isFullyPrivate } from "./services/privacy.js";
import { createCompactionHook } from "./services/compaction.js";
import { CONFIG, isInitialized } from "./config.js";
import { log } from "./services/logger.js";
const CODE_BLOCK_PATTERN = /```[\s\S]*?```/g;
const INLINE_CODE_PATTERN = /`[^`]+`/g;
const MEMORY_KEYWORD_PATTERN = new RegExp(`\\b(${CONFIG.keywordPatterns.join("|")})\\b`, "i");
const MEMORY_NUDGE_MESSAGE = `[MEMORY TRIGGER DETECTED]
The user wants you to remember something. You MUST use the \`local-memory\` tool with \`mode: "add"\` to save this information.

Extract the key information the user wants remembered and save it as a concise, searchable memory.
- Use \`scope: "project"\` for project-specific preferences (e.g., "run lint with tests")
- Use \`scope: "user"\` for cross-project preferences (e.g., "prefers concise responses")
- Choose an appropriate \`type\`: "preference", "project-config", "learned-pattern", etc.

DO NOT skip this step. The user explicitly asked you to remember.`;
const REFLECTION_NUDGE_MESSAGE = `[MEMORY CONSOLIDATION NEEDED]
This project has accumulated raw session/conversation memories. Distill them into durable knowledge:

1. Use \`local-memory\` with \`mode: "search"\` (query by topic) and \`mode: "list"\` to review recent conversation-type memories.
2. Identify repeated patterns, resolved errors, and stable architectural facts.
3. For each insight, use \`mode: "add"\` with \`type: "learned-pattern"\` (or "architecture" / "error-solution") and a concise, generalizable statement.
4. Use \`mode: "forget"\` to delete the raw conversation memories you distilled (pass each memoryId).

Keep the distilled memories short and searchable. Do not invent facts that are not backed by the raw memories.`;
function removeCodeBlocks(text) {
    return text.replace(CODE_BLOCK_PATTERN, "").replace(INLINE_CODE_PATTERN, "");
}
function detectMemoryKeyword(text) {
    const textWithoutCode = removeCodeBlocks(text);
    return MEMORY_KEYWORD_PATTERN.test(textWithoutCode);
}
export const LocalMemoryPlugin = async (ctx) => {
    const { directory } = ctx;
    const tags = getTags(directory);
    const injectedSessions = new Set();
    log("Plugin init", { directory, tags, initialized: isInitialized() });
    if (!isInitialized()) {
        log("Plugin disabled - not initialized. Run 'opencode-mem init' first.");
    }
    if (isInitialized()) {
        const { embeddingService } = await import("./services/embedding.js");
        embeddingService.preload();
    }
    const modelLimits = new Map();
    let modelLimitsLoaded = false;
    let modelLimitsLoading = false;
    async function loadModelLimits() {
        if (modelLimitsLoaded || modelLimitsLoading)
            return;
        modelLimitsLoading = true;
        try {
            const response = await ctx.client.provider.list();
            if (response.data?.all) {
                for (const provider of response.data.all) {
                    if (provider.models) {
                        for (const [modelId, model] of Object.entries(provider.models)) {
                            if (model.limit?.context) {
                                modelLimits.set(`${provider.id}/${modelId}`, model.limit.context);
                            }
                        }
                    }
                }
            }
            modelLimitsLoaded = true;
            log("Model limits loaded", { count: modelLimits.size });
        }
        catch (error) {
            log("Failed to fetch model limits", { error: String(error) });
        }
        finally {
            modelLimitsLoading = false;
        }
    }
    const getModelLimit = (providerID, modelID) => {
        return modelLimits.get(`${providerID}/${modelID}`);
    };
    const compactionHook = isInitialized() && ctx.client
        ? createCompactionHook(ctx, tags, directory, {
            threshold: CONFIG.compactionThreshold,
            getModelLimit,
            loadModelLimits,
        })
        : null;
    return {
        "chat.message": async (input, output) => {
            if (!isInitialized())
                return;
            const start = Date.now();
            try {
                const textParts = output.parts.filter((p) => p.type === "text");
                if (textParts.length === 0) {
                    log("chat.message: no text parts found");
                    return;
                }
                const userMessage = textParts.map((p) => p.text).join("\n");
                if (!userMessage.trim()) {
                    log("chat.message: empty message, skipping");
                    return;
                }
                log("chat.message: processing", {
                    messagePreview: userMessage.slice(0, 100),
                    partsCount: output.parts.length,
                    textPartsCount: textParts.length,
                });
                if (detectMemoryKeyword(userMessage)) {
                    log("chat.message: memory keyword detected");
                    const nudgePart = {
                        id: `local-memory-nudge-${Date.now()}`,
                        sessionID: input.sessionID,
                        messageID: output.message.id,
                        type: "text",
                        text: MEMORY_NUDGE_MESSAGE,
                        synthetic: true,
                    };
                    output.parts.push(nudgePart);
                }
                const isFirstMessage = !injectedSessions.has(input.sessionID);
                if (isFirstMessage) {
                    injectedSessions.add(input.sessionID);
                    const store = getStore(CONFIG.storageLocation, directory);
                    const [userMemoriesResult, projectMemoriesList, conversationCount] = await Promise.all([
                        store.searchMemories(userMessage, tags.user, {
                            threshold: CONFIG.similarityThreshold,
                            limit: CONFIG.maxMemories,
                        }),
                        store.listMemories(tags.project, CONFIG.maxProjectMemories, ["opencode-mem_project_default", "mem_project_default"]),
                        store.countByType(tags.project, "conversation"),
                    ]);
                    // Promotion chain: too many raw conversation memories → ask the
                    // agent (the only LLM available offline) to distill them into
                    // learned-pattern / architecture / error-solution knowledge.
                    if (CONFIG.reflectionEnabled && conversationCount >= CONFIG.reflectionThreshold) {
                        log("chat.message: reflection nudge", { conversationCount });
                        output.parts.push({
                            id: `local-memory-reflect-${Date.now()}`,
                            sessionID: input.sessionID,
                            messageID: output.message.id,
                            type: "text",
                            text: REFLECTION_NUDGE_MESSAGE,
                            synthetic: true,
                        });
                    }
                    const projectMemories = projectMemoriesList.map((m) => ({
                        id: m.id,
                        content: m.content,
                        similarity: 1,
                        scope: m.scope,
                        type: m.type,
                        createdAt: m.createdAt,
                    }));
                    const profile = generateUserProfile(userMemoriesResult);
                    const memoryContext = formatContextForPrompt({
                        profile,
                        userMemories: userMemoriesResult,
                        projectMemories,
                    });
                    if (memoryContext) {
                        const contextPart = {
                            id: `local-memory-context-${Date.now()}`,
                            sessionID: input.sessionID,
                            messageID: output.message.id,
                            type: "text",
                            text: memoryContext,
                            synthetic: true,
                        };
                        output.parts.unshift(contextPart);
                        const duration = Date.now() - start;
                        log("chat.message: context injected", {
                            duration,
                            contextLength: memoryContext.length,
                        });
                    }
                }
                else if (CONFIG.perMessageRetrieval) {
                    // On-demand retrieval: search memories relevant to this specific
                    // message and inject only when something clears the threshold.
                    const store = getStore(CONFIG.storageLocation, directory);
                    const [userHits, projectHits] = await Promise.all([
                        store.searchMemories(userMessage, tags.user, {
                            threshold: CONFIG.similarityThreshold,
                            limit: CONFIG.perMessageMaxMemories,
                        }),
                        store.searchMemories(userMessage, tags.project, {
                            threshold: CONFIG.similarityThreshold,
                            limit: CONFIG.perMessageMaxMemories,
                        }),
                    ]);
                    if (userHits.length > 0 || projectHits.length > 0) {
                        const lines = ["[LOCAL-MEMORY] Relevant to this message:"];
                        for (const m of projectHits) {
                            lines.push(`- [project|${Math.round(m.similarity * 100)}%] ${m.content}`);
                        }
                        for (const m of userHits) {
                            lines.push(`- [user|${Math.round(m.similarity * 100)}%] ${m.content}`);
                        }
                        const contextPart = {
                            id: `local-memory-msg-${Date.now()}`,
                            sessionID: input.sessionID,
                            messageID: output.message.id,
                            type: "text",
                            text: lines.join("\n"),
                            synthetic: true,
                        };
                        output.parts.unshift(contextPart);
                        log("chat.message: per-message memories injected", {
                            userHits: userHits.length,
                            projectHits: projectHits.length,
                        });
                    }
                }
            }
            catch (error) {
                log("chat.message: ERROR", { error: String(error) });
            }
        },
        tool: {
            "local-memory": tool({
                description: "Manage and query the local persistent memory system. Use 'search' to find relevant memories, 'add' to store new knowledge, 'list' to see recent memories, 'forget' to remove a memory.",
                args: {
                    mode: tool.schema
                        .enum(["add", "search", "list", "forget", "profile", "help"])
                        .optional(),
                    content: tool.schema.string().optional(),
                    query: tool.schema.string().optional(),
                    type: tool.schema
                        .enum([
                        "preference",
                        "project-config",
                        "architecture",
                        "error-solution",
                        "learned-pattern",
                        "conversation",
                    ])
                        .optional(),
                    scope: tool.schema.enum(["user", "project"]).optional(),
                    all: tool.schema.boolean().optional(),
                    project: tool.schema.string().optional(),
                    memoryId: tool.schema.string().optional(),
                    limit: tool.schema.number().optional(),
                },
                async execute(args) {
                    if (!isInitialized()) {
                        return JSON.stringify({
                            success: false,
                            error: "Local memory not initialized. Run 'opencode-mem init' first.",
                        });
                    }
                    const mode = args.mode || "help";
                    const store = getStore(CONFIG.storageLocation, directory);
                    try {
                        switch (mode) {
                            case "help": {
                                return JSON.stringify({
                                    success: true,
                                    message: "Local Memory Usage Guide",
                                    commands: [
                                        {
                                            command: "add",
                                            description: "Store a new memory",
                                            args: ["content", "type?", "scope?"],
                                        },
                                        {
                                            command: "search",
                                            description: "Search memories",
                                            args: ["query", "scope?"],
                                        },
                                        {
                                            command: "profile",
                                            description: "View user profile",
                                            args: [],
                                        },
                                        {
                                            command: "list",
                                            description: "List memories (use all=true to list all projects)",
                                            args: ["scope?", "limit?", "all?"],
                                        },
                                        {
                                            command: "forget",
                                            description: "Remove a memory",
                                            args: ["memoryId"],
                                        },
                                    ],
                                    scopes: {
                                        user: "Cross-project preferences and knowledge",
                                        project: "Project-specific knowledge (default)",
                                    },
                                    types: [
                                        "preference",
                                        "project-config",
                                        "architecture",
                                        "error-solution",
                                        "learned-pattern",
                                        "conversation",
                                    ],
                                });
                            }
                            case "add": {
                                if (!args.content) {
                                    return JSON.stringify({
                                        success: false,
                                        error: "content parameter is required for add mode",
                                    });
                                }
                                const sanitizedContent = stripPrivateContent(args.content);
                                if (isFullyPrivate(args.content)) {
                                    return JSON.stringify({
                                        success: false,
                                        error: "Cannot store fully private content",
                                    });
                                }
                                const scope = args.scope || "project";
                                const containerTag = scope === "user" ? tags.user : tags.project;
                                const result = await store.addMemory({
                                    content: sanitizedContent,
                                    scope,
                                    type: args.type || "learned-pattern",
                                    containerTag,
                                    projectName: scope === "project" ? getProjectName(directory) : undefined,
                                    projectPath: scope === "project" ? directory : undefined,
                                });
                                return JSON.stringify({
                                    success: true,
                                    message: `Memory added to ${scope} scope`,
                                    id: result.id,
                                    scope,
                                    type: args.type,
                                });
                            }
                            case "search": {
                                if (!args.query) {
                                    return JSON.stringify({
                                        success: false,
                                        error: "query parameter is required for search mode",
                                    });
                                }
                                const scope = args.scope;
                                if (scope === "user") {
                                    const result = await store.searchMemories(args.query, tags.user, { threshold: CONFIG.similarityThreshold, limit: args.limit || 10 });
                                    return formatSearchResults(args.query, scope, result, args.limit);
                                }
                                if (scope === "project") {
                                    const result = await store.searchMemories(args.query, tags.project, { threshold: CONFIG.similarityThreshold, limit: args.limit || 10 });
                                    return formatSearchResults(args.query, scope, result, args.limit);
                                }
                                const [userResult, projectResult] = await Promise.all([
                                    store.searchMemories(args.query, tags.user, {
                                        threshold: CONFIG.similarityThreshold,
                                        limit: args.limit || 10,
                                    }),
                                    store.searchMemories(args.query, tags.project, {
                                        threshold: CONFIG.similarityThreshold,
                                        limit: args.limit || 10,
                                    }),
                                ]);
                                const combined = [
                                    ...userResult.map((r) => ({ ...r, scope: "user" })),
                                    ...projectResult.map((r) => ({ ...r, scope: "project" })),
                                ].sort((a, b) => b.similarity - a.similarity);
                                return JSON.stringify({
                                    success: true,
                                    query: args.query,
                                    count: combined.length,
                                    results: combined.slice(0, args.limit || 10).map((r) => ({
                                        id: r.id,
                                        content: r.content,
                                        similarity: Math.round(r.similarity * 100),
                                        scope: r.scope,
                                    })),
                                });
                            }
                            case "profile": {
                                const userMemories = await store.searchMemories("", tags.user, {
                                    threshold: 0,
                                    limit: 20,
                                });
                                const profile = generateUserProfile(userMemories);
                                return JSON.stringify({
                                    success: true,
                                    profile,
                                });
                            }
                            case "list": {
                                const limit = args.limit || 100;
                                let memories;
                                if (args.all) {
                                    memories = await store.listAllMemories(limit);
                                }
                                else if (args.project) {
                                    memories = await store.listMemoriesByProject(args.project, limit);
                                }
                                else {
                                    const scope = args.scope || "project";
                                    const containerTag = scope === "user" ? tags.user : tags.project;
                                    const oldTags = scope === "user"
                                        ? ["opencode-mem_user_default", "mem_user_default"]
                                        : ["opencode-mem_project_default", "mem_project_default"];
                                    memories = await store.listMemories(containerTag, limit, oldTags);
                                }
                                return JSON.stringify({
                                    success: true,
                                    count: memories.length,
                                    memories: memories.map((m) => ({
                                        id: m.id,
                                        content: m.content.length > 20 ? m.content.slice(0, 20) + "..." : m.content,
                                        projectName: m.projectName,
                                        scope: m.scope,
                                        createdAt: m.createdAt,
                                        type: m.type,
                                    })),
                                });
                            }
                            case "forget": {
                                if (!args.memoryId) {
                                    return JSON.stringify({
                                        success: false,
                                        error: "memoryId parameter is required for forget mode",
                                    });
                                }
                                const deleted = await store.deleteMemory(args.memoryId);
                                if (!deleted) {
                                    return JSON.stringify({
                                        success: false,
                                        error: "Memory not found or could not be deleted",
                                    });
                                }
                                return JSON.stringify({
                                    success: true,
                                    message: `Memory ${args.memoryId} removed`,
                                });
                            }
                            default:
                                return JSON.stringify({
                                    success: false,
                                    error: `Unknown mode: ${mode}`,
                                });
                        }
                    }
                    catch (error) {
                        return JSON.stringify({
                            success: false,
                            error: error instanceof Error ? error.message : String(error),
                        });
                    }
                },
            }),
        },
        event: async (input) => {
            if (compactionHook) {
                await compactionHook.event(input);
            }
        },
    };
};
function formatSearchResults(query, scope, results, limit) {
    return JSON.stringify({
        success: true,
        query,
        scope,
        count: results.length,
        results: results.slice(0, limit || 10).map((r) => ({
            id: r.id,
            content: r.content,
            similarity: Math.round(r.similarity * 100),
        })),
    });
}
export default LocalMemoryPlugin;
